const items = $input.all();
const result = [];
for (const item of items) {
  const key = Object.keys(item.json).find(k => k.startsWith('state:'));
  if (!key) continue;
  const raw = item.json[key];
  if (!raw) continue;
  try {
    const s = JSON.parse(raw);
    const chatId = key.replace('state:', '');
    if (s.ts && s.step && (Date.now() - s.ts) > 600000) {
      result.push({ json: { key, chatId } });
    }
  } catch(e) {}
}
return result;

